INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('418660', 'hiddenInsight', NULL, '미국 주식으로 구성된 ''NASDAQ-100 지수(원화환산)''를 기초지수로 하여 1좌당 순자산가치의 일간변동률을 기초지수 일간변동률의 양(陽)의 2배수로 연동하여 투자신탁재산을 운용함을 목적으로 합니다.', NULL, '투자설명서 제2부 9 (운용목표·운용방법)', 'KR_PROSPECTUS', FALSE, 1);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('418660', NULL, 'W-LEV-01', '1좌당 순자산가치의 일간변동률을 기초지수 일간변동률의 양(陽)의 2배수로 연동하여 투자신탁재산을 운용함을 목적으로 합니다.', NULL, '제2부 9 (운용목표)', 'KR_PROSPECTUS', FALSE, 2);
