INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('418660', NULL, 'W-FX-01', '환헤지를 하지 아니함', NULL, '제2부 9 (환헤지 사항)', 'KR_PROSPECTUS', FALSE, 4);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('418660', NULL, 'I-SYN-01', '구성종목에 TRS 계약이 편입되어 있음(예: 미국나스닥100 TRS 1~~3). 거래상대방은 상품페이지 공시 명단(미래에셋증권·한국투자증권·NH투자증권·KB증권·삼성증권·신한금융투자·메리츠증권·키움증권, 신용등급 AA~~AA+)', NULL, '제2부 9 (운용방법) / 구성종목 공시', 'KR_PROSPECTUS', FALSE, 5);
