INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('448290', 2, '미국S&P500', NULL, '미국 큰 회사 500개를 그대로 따라가고');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('448290', 3, '(H)', NULL, '환율 걱정은 없는 상품');
INSERT INTO etf_hidden_insight (code, summary, body) VALUES ('448290', '환율 걱정은 없지만 비용이 듭니다', '(H)는 환율 변동을 막는 장치입니다. 대신 그 장치를 유지하는 비용이 수익률에서 빠집니다.');
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('448290', 'hiddenInsight', NULL, '이 투자신탁은 S&P Dow Jones Indices에서 발표하는 ''S&P 500''를 기초지수로 하는 상장지수투자신탁으로서, 미국에 상장된 주식에 투자신탁 자산총액의 60% 이상 투자합니다. 한편, 동 ETF는 환헤지형으로서 별도의 환위험헤지전략을 수행합니다.', NULL, '투자설명서 제2부 9 (운용방법)', 'KR_PROSPECTUS', FALSE, 1);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('448290', NULL, 'W-TR-01', '지급기준일 : 1, 4, 7, 10월 마지막영업일, 회계기간종료일(비영업일인 경우 직전영업일)', NULL, '제2부 14-가 (이익 배분)', 'KR_PROSPECTUS', FALSE, 2);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('448290', NULL, 'I-FXH-01', '동 ETF는 환헤지형으로서 별도의 환위험헤지전략을 수행합니다.', NULL, '제2부 9 (운용방법)', 'KR_PROSPECTUS', FALSE, 3);
INSERT INTO etf_master (code, isin, name, market, manager, listed_at, exchange, source, display_order) VALUES ('QYLD', NULL, 'Global X NASDAQ 100 Covered Call ETF', 'US', 'Global X', NULL, 'NASDAQ', 'manual', 8);
INSERT INTO etf_profile (code, base_index, replication, leverage, daily_rebalancing, is_active, strategy, distribution, distribution_yield, target_year, total_expense, fx_hedge, counterparty_risk, counterparty, main_assets, is_complex_product, extracted_by, extraction_run_id, reviewed_at) VALUES ('QYLD', 'Cboe NASDAQ-100 BuyWrite V2', '실물', 1.0, FALSE, FALSE, '커버드콜', '월분배', 11.5, NULL, 0.6, '미헤지', FALSE, NULL, ARRAY['NASDAQ 100', 'Covered Call']::text[], FALSE, 'manual', NULL, '2026-08-31 00:00:00+09:00');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('QYLD', 1, 'Global X', NULL, '글로벌엑스가 만든');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('QYLD', 2, 'NASDAQ 100', NULL, '미국 기술주 100개를 담고');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('QYLD', 3, 'Covered Call', NULL, '매달 돈을 받는 대신 큰 상승은 포기하는');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('QYLD', 4, 'ETF', NULL, '상품');
INSERT INTO etf_hidden_insight (code, summary, body) VALUES ('QYLD', '나스닥이 크게 올라도 그만큼 못 받아요', '커버드콜은 앞으로 오를 수 있는 몫을 미리 팔아 매달 분배금을 만듭니다. 그래서 크게 오르는 구간에서 그 상승분을 온전히 받지 못합니다.');
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('QYLD', 'hiddenInsight', NULL, '커버드콜 옵션을 매도함으로써 이 펀드는 옵션 행사가격을 초과하는 참조지수 가치 상승분의 이익을 포기하게 되며, 하락에 대한 위험은 계속 부담할 수 있습니다.', 'By writing covered call options on a portion of the Fund''s portfolio in return for the receipt of premiums, the Fund will give up the opportunity to benefit from potential increases in the value of the Reference Index above the exercise prices of such options, but may continue to bear the risk of declines in the value of the Reference Index.', '요약투자설명서 — 주요 투자전략 (Summary Prospectus, SEC 공시)', 'US_SUMMARY_PROSPECTUS', TRUE, 1);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('QYLD', NULL, 'W-CC-01', '커버드콜 옵션을 매도함으로써 이 펀드는 옵션 행사가격을 초과하는 참조지수 가치 상승분의 이익을 포기하게 됩니다.', NULL, '요약투자설명서 — 주요 투자전략 (Summary Prospectus, SEC 공시)', 'US_SUMMARY_PROSPECTUS', TRUE, 2);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('QYLD', NULL, 'I-DIV-01', '2014년 1월부터 2026년 8월까지 매월 빠짐없이 분배금을 지급한 지급기준일(ex-date)·기준일(record date)·지급일(payable date)·금액 내역이 공시되어 있습니다 (예: 2026-08-24 지급기준일, 주당 $0.1829).', NULL, '운용사 법정 공시 영역 — Distribution History (globalxetfs.com/funds/qyld)', 'ISSUER_DISCLOSURE', TRUE, 3);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('QYLD', NULL, 'I-FX-01', '환헤지를 하지 아니함', NULL, '제2부 9', 'US_SUMMARY_PROSPECTUS', TRUE, 4);
