INSERT INTO etf_profile (code, base_index, replication, leverage, daily_rebalancing, is_active, strategy, distribution, distribution_yield, target_year, total_expense, fx_hedge, counterparty_risk, counterparty, main_assets, is_complex_product, extracted_by, extraction_run_id, reviewed_at) VALUES ('TQQQ', 'Nasdaq-100', '합성', 3.0, TRUE, FALSE, '레버리지', '분기분배', 0.5, NULL, 0.82, '미헤지', TRUE, NULL, ARRAY['스왑 계약', '선물 계약']::text[], FALSE, 'ai', NULL, '2026-09-02 00:00:00+09:00');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('TQQQ', 1, 'ProShares', NULL, '프로셰어스가 만든');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('TQQQ', 2, 'UltraPro', NULL, '3배로');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('TQQQ', 3, 'QQQ', NULL, '미국 기술주 100개(나스닥100)를');
INSERT INTO etf_name_token (code, seq, text, absent, translation) VALUES ('TQQQ', 4, NULL, '방향 표기 없음', '같은 방향으로 따라가는 상품');
INSERT INTO etf_hidden_insight (code, summary, body) VALUES ('TQQQ', '이름에 ''3배''라는 말이 없어요', '''UltraPro''가 3배를 뜻합니다. 그리고 이 3배는 하루 단위로만 맞춰집니다. 설명서에는 "지수가 장중 33% 하락에 근접하면 투자금 전액을 잃을 수 있다"고 적혀 있습니다.');
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('TQQQ', 'hiddenInsight', NULL, '이 펀드는 하루를 제외한 어떤 기간에 대해서도 지수의 일간 성과의 3배(3x)를 달성하는 것을 목표로 하지 않습니다.', 'The Fund does not seek to achieve three times (3x) the daily performance of the Index (the "Daily Target") for any period other than a day.', '요약투자설명서 — 주요 정보 (Summary Prospectus, SEC 공시)', 'US_SUMMARY_PROSPECTUS', TRUE, 1);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('TQQQ', NULL, 'W-LEV-01', '이 펀드는 하루를 제외한 어떤 기간에 대해서도 지수의 일간 성과의 3배를 달성하는 것을 목표로 하지 않습니다.', 'The Fund does not seek to achieve three times (3x) the daily performance of the Index (the "Daily Target") for any period other than a day.', '요약투자설명서 — 주요 정보 / 주요 위험 (Summary Prospectus, SEC 공시)', 'US_SUMMARY_PROSPECTUS', TRUE, 2);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('TQQQ', NULL, 'W-LEV-01', '지수가 장중 33% 손실에 근접하면 투자금 전액을 잃을 수 있습니다.', 'If the Index approaches a 33% loss at any point in the day, you could lose your entire investment.', '요약투자설명서 — 주요 정보 / 주요 위험 (Summary Prospectus, SEC 공시)', 'US_SUMMARY_PROSPECTUS', TRUE, 3);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('TQQQ', NULL, 'W-TR-01', '지급기준일 : 회계기간종료일(비영업일인 경우 직전영업일)', NULL, '제2부 14-가 (이익 배분)', 'US_SUMMARY_PROSPECTUS', TRUE, 4);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('TQQQ', NULL, 'W-FX-01', '환헤지를 하지 아니함', NULL, '제2부 9 (환헤지 사항)', 'US_SUMMARY_PROSPECTUS', TRUE, 5);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('TQQQ', NULL, 'I-SYN-01', '이 펀드는 스왑 계약과 선물 계약을 통해 지수 노출을 확보합니다.', NULL, '요약투자설명서 — 주요 투자전략 (Summary Prospectus, SEC 공시)', 'US_SUMMARY_PROSPECTUS', TRUE, 6);
INSERT INTO evidence (code, field, rule_code, quote, quote_original, location, source_type, translated, display_order) VALUES ('TQQQ', NULL, 'I-FX-01', '환헤지를 하지 아니함', NULL, '제2부 9', 'US_SUMMARY_PROSPECTUS', TRUE, 7);
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('W-LEV-01', 'warning', 1, '원금 손실', '오래 들고 있으면 손해 볼 수 있어요', '{기간} 보유하실 계획과 맞지 않습니다', '이 상품은 하루 단위로 지수의 {배율}배를 맞추도록 만들어졌습니다. 지수가 올랐다 내렸다를 반복하면, {기간} 뒤에는 지수가 제자리여도 원금이 줄어 있을 수 있습니다.', '꼭 필요한 돈이라고 하셨는데, 이 상품은 원금이 예상보다 크게 줄어들 수 있는 구조입니다.', 'A');
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('W-MIX-01', 'warning', 2, '목적 불일치', '나스닥이 올라도 그만큼 따라가지 못해요', '차익을 노리는 목적과 맞지 않을 수 있습니다', '이름 앞에 ''미국나스닥100''이 있어 기술주 상품으로 보이지만, 이름 끝의 ''50''은 주식과 채권을 반반씩 담는다는 뜻입니다. 채권을 섞은 만큼 나스닥이 크게 올라도 그만큼 따라가지 못합니다.', '목표한 금액을 모으려는 계획이라면, 기대하신 속도보다 천천히 불어날 수 있다는 점을 감안하셔야 합니다.', 'C');
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('W-CC-01', 'warning', 2, '목적 불일치', '가격이 올라도 그만큼 못 받아요', '차익을 노리는 목적과 맞지 않습니다', '이 상품이 매달 주는 돈은, 앞으로 오를 수 있는 몫을 미리 팔아서 만듭니다. 그래서 크게 오르는 구간에서 그 상승분을 온전히 받지 못합니다.', '목표한 금액이 있으시다면, 시장이 크게 올라도 그만큼 따라가지 못한다는 점을 미리 아셔야 합니다.', 'B');
INSERT INTO rule_config_variant (rule_code, purpose, summary, title, body) VALUES ('W-CC-01', 'CAPITAL_GAIN', '가격이 올라도 그만큼 못 받아요', '차익을 노리는 목적과 맞지 않습니다', '이 상품이 매달 주는 돈은, 앞으로 오를 수 있는 몫을 미리 팔아서 만듭니다. 그래서 크게 오르는 구간에서 그 상승분을 온전히 받지 못합니다.');
INSERT INTO rule_config_variant (rule_code, purpose, summary, title, body) VALUES ('W-CC-01', 'GROWTH', '오래 둘수록 지수와 차이가 벌어져요', '오래 묻어두는 목적과 맞지 않습니다', '이 상품이 매달 주는 돈은, 앞으로 오를 수 있는 몫을 미리 팔아서 만듭니다. 이 차이는 오래 둘수록 쌓입니다. 같은 구조의 상품(QYLD)은 지난 10년간 8.79% 올랐고, 같은 기간 나스닥100 지수는 19.70% 올랐습니다.');
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('W-TR-01', 'warning', 3, '현금 흐름', '매달 받는 돈이 없어요', '정기적으로 현금을 받고 싶다는 목적과 맞지 않습니다', '이 상품은 1년에 한 번, 그것도 적은 금액만 나눠줍니다. 매달 현금이 필요하시다면 직접 팔아야 합니다.', '정해진 시점에 돈이 필요하시다면, 그때 시장 상황이 나빠도 팔아야 할 수 있습니다.', 'E');
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('W-FX-01', 'warning', 3, '현금 흐름', '환율에 따라 받는 돈이 달라져요', '안정적인 현금 목적과 맞지 않을 수 있습니다', '환율 변동을 막는 장치가 없습니다. 받는 돈이 환율에 따라 달라집니다.', '매달 일정한 금액이 필요하신 상황이라면, 환율에 따라 들쑥날쑥해질 수 있다는 점을 감안하셔야 합니다.', 'D');
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('I-SYN-01', 'info', NULL, NULL, '주식을 직접 사지 않고 증권사와 약속만 했어요', NULL, '이 상품은 {기초자산}을 직접 사는 대신, 증권사와 계약(TRS)을 맺어 수익률을 받는 구조입니다. 해외 지수를 따라갈 때는 이 방식이 오히려 오차가 작은 경우가 많습니다. 다만 계약 상대방(**{거래상대방}**)이 약속을 지키지 못할 경우 영향을 받을 수 있다는 점은 실제로 주식을 갖고 있는 것과 다른 부분입니다.', NULL, NULL);
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('I-FX-01', 'info', NULL, NULL, '환율에 따라 수익이 달라져요', NULL, '환율 변동을 막는 장치가 없습니다. 미국 주가가 올라도 원달러 환율이 떨어지면 수익이 줄어들 수 있고, 반대로 환율이 오르면 수익이 늘어날 수도 있습니다.', NULL, NULL);
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('I-FXH-01', 'info', NULL, NULL, '환율이 오르내려도 크게 상관없어요', NULL, '원달러 환율이 변해도 수익률에 미치는 영향이 작습니다. 대신 그 장치를 유지하는 비용이 듭니다.', NULL, NULL);
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('I-DIV-01', 'info', NULL, NULL, '매달 돈을 나눠줘요', NULL, '매월 마지막 영업일 기준으로 분배금을 지급합니다. 다만 그 돈이 어디서 나오는지(수익인지, 원금인지) 함께 살펴보시는 것이 좋습니다.', NULL, NULL);
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('I-MIX-01', 'info', NULL, NULL, '주식과 채권을 함께 담고 있어요', NULL, '하나의 상품 안에 주식과 채권이 함께 들어 있습니다. 주식만 담은 상품보다 덜 흔들리지만, 크게 오를 때도 덜 오릅니다.', NULL, NULL);
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('I-OVS-01', 'info', NULL, NULL, '이 상품은 미국에 상장되어 있어요', NULL, '한국에서 이 상품을 살 때는, 투자설명서를 확인하는 절차가 법적으로 요구되지 않습니다. 국내 상장 상품과 달리 한국어 설명서도 없습니다. 저희가 미국 공시 문서(SEC)를 대신 읽어 정리했습니다.', NULL, NULL);
INSERT INTO rule_config (code, level, priority, category, summary, title, body, purpose_addon, widget_type) VALUES ('OK-01', 'ok', NULL, NULL, '선택하신 조건 기준으로 어긋나는 부분은 발견되지 않았습니다', NULL, '다만 모든 투자에는 원금 손실 가능성이 있습니다.', NULL, NULL);
